    runtime.active_agent_sessions.insert(
        window_id.clone(),
        sample_active_agent_session("tab-1", &window_id),
    );

    let events = (0..1_000)
        .flat_map(|_| runtime.handle_runtime_hook_event(runtime_hook_state("Waiting", "session-1")))
        .collect::<Vec<_>>();

